import Foundation

/// Starting scenario: 30 May 1453, the day after Mehmed II took Constantinople.
///
/// The data lives in `Resources/scenario1453.json`, generated by
/// `tools/mapgen/mapgen.py` from the hand-written files in `data/map/`.
public enum Scenario1453 {
    public static let startDate = GameDate(year: 1453, month: 5, day: 30)
    public static let defaultPlayerTag = "TUR"
    /// Months the market runs before the start so prices are settled.
    public static let warmUpMonths = 12

    public enum LoadError: Error {
        case missingResource
        case unknownValue(String)
    }

    /// Loads the bundled 1453 scenario. The file is read once; every call
    /// returns a fresh copy of the starting world.
    public static func makeWorld() -> World {
        switch cachedStart {
        case .success(let world): return world
        case .failure(let error): preconditionFailure("Could not load scenario1453.json: \(error)")
        }
    }

    private static let cachedStart: Result<World, Error> = Result { try loadBundled() }

    public static func loadBundled() throws -> World {
        guard let url = Bundle.module.url(forResource: "scenario1453", withExtension: "json") else {
            throw LoadError.missingResource
        }
        var world = try load(from: Data(contentsOf: url))
        try EconomyLoader.loadBundled(into: &world)
        try CharacterLoader.loadBundled(into: &world)
        MarketSystem.warmUp(&world, months: warmUpMonths)
        return world
    }

    public static func load(from data: Data) throws -> World {
        let file = try JSONDecoder().decode(ScenarioFile.self, from: data)
        return try build(file)
    }

    // MARK: - Starting values derived from development

    /// People living in a province of the given development.
    static func startingPopulation(development: Int) -> Double {
        let d = Double(max(development, 1))
        return (d * d.squareRoot() * 8_000).rounded()
    }

    static func startingTax(development: Int) -> Double {
        Double(development) * 0.8 + 0.2
    }

    static func startingProduction(development: Int) -> Double {
        Double(development) * 0.6
    }

    static func startingFort(development: Int, isCapital: Bool) -> Int {
        let base: Int
        switch development {
        case 8...: base = 3
        case 5...7: base = 2
        case 3...4: base = 1
        default: base = 0
        }
        return min(base + (isCapital ? 1 : 0), 4)
    }

    static func startingTreasury(totalDevelopment: Int) -> Double {
        (Double(totalDevelopment) * 3).rounded()
    }

    // MARK: - Building the world

    /// Splits each province's people into pops by culture, religion, sect
    /// and social class, from the shares in the scenario file.
    private static func buildPops(_ file: ScenarioFile, into world: inout World) throws {
        for (index, p) in file.provinces.enumerated() {
            let id = ProvinceID(index)
            world.pops.beginProvince(id)
            let total = world.provinces.population[index]
            var groups: [(culture: CultureID, family: String, religion: Religion, sect: Sect?, size: Double)] = []
            for entry in p.pops ?? [] {
                guard entry.culture < world.cultures.count else { throw LoadError.unknownValue("culture \(entry.culture)") }
                guard let religion = Religion(rawValue: entry.religion) else { throw LoadError.unknownValue("religion \(entry.religion)") }
                var sect: Sect?
                if let name = entry.sect {
                    guard let s = Sect(rawValue: name) else { throw LoadError.unknownValue("sect \(name)") }
                    sect = s
                }
                let culture = CultureID(entry.culture)
                groups.append((culture, world.cultures.family[culture.index], religion, sect, total * entry.share))
            }
            if groups.isEmpty {
                // No data: everyone follows the ruler's faith, culture unknown (first culture).
                let religion = world.provinces.religion[index]
                groups.append((CultureID(0), world.cultures.count > 0 ? world.cultures.family[0] : "", religion, nil, total))
            }
            let owner = world.provinces.owner[index]
            let targets = ClassSplit.targets(
                development: world.provinces.development[index],
                government: owner.map { world.countries.government[$0.index] },
                slavery: owner.map { world.countries.slavery[$0.index] } ?? 0
            )
            let split = ClassSplit.split(
                groups: groups,
                targets: targets,
                rulerReligion: owner.map { world.countries.religion[$0.index] }
            )
            // Keep rows tidy: group first, then class order.
            let order = Dictionary(uniqueKeysWithValues: SocialClass.allCases.enumerated().map { ($1, $0) })
            for row in split.sorted(by: { $0.group == $1.group ? order[$0.socialClass]! < order[$1.socialClass]! : $0.group < $1.group }) {
                let g = groups[row.group]
                world.pops.add(culture: g.culture, religion: g.religion, sect: g.sect, socialClass: row.socialClass, size: row.size)
            }
            world.provinces.sufiOrders[index] = (p.orders ?? []).compactMap { pair in
                guard let order = SufiOrder(rawValue: pair.order) else { return nil }
                return SufiPresence(order: order, strength: pair.strength)
            }
        }
        world.refreshProvinceSummaries()
    }

    private static func build(_ file: ScenarioFile) throws -> World {
        var world = World(map: MapInfo(
            width: file.map.width,
            height: file.map.height,
            pixelsPerDegree: file.map.pixelsPerDegree,
            longitudeMin: file.map.longitudeMin,
            latitudeMax: file.map.latitudeMax
        ))
        world.regions = file.regions
        for c in file.cultures ?? [] {
            world.cultures.add(key: c.id, name: c.name, family: c.family)
        }
        for state in file.states {
            world.states.add(name: state.name, region: RegionID(state.region))
        }

        // Total development per country, for starting treasuries.
        var devByTag: [String: Int] = [:]
        for p in file.provinces {
            if let owner = p.owner { devByTag[owner, default: 0] += p.development }
        }

        for c in file.countries {
            guard let government = GovernmentType(rawValue: c.government) else {
                throw LoadError.unknownValue("government \(c.government)")
            }
            guard let religion = Religion(rawValue: c.religion) else {
                throw LoadError.unknownValue("religion \(c.religion)")
            }
            world.countries.add(
                tag: c.tag,
                name: c.name,
                color: RGB(UInt8(c.color[0]), UInt8(c.color[1]), UInt8(c.color[2])),
                government: government,
                religion: religion,
                treasury: startingTreasury(totalDevelopment: devByTag[c.tag] ?? 0)
            )
            world.countries.slavery[world.countries.count - 1] = c.slavery ?? 0
        }
        let capitals = Set(file.countries.map(\.capital))

        for (index, p) in file.provinces.enumerated() {
            guard let terrain = Terrain(rawValue: p.terrain) else {
                throw LoadError.unknownValue("terrain \(p.terrain)")
            }
            var owner: CountryID?
            if let tag = p.owner {
                guard let id = world.countries.id(forTag: tag) else {
                    throw LoadError.unknownValue("owner \(tag)")
                }
                owner = id
            }
            world.addProvince(
                name: p.name,
                location: GeoPoint(latitude: p.latitude, longitude: p.longitude),
                state: StateID(p.state),
                terrain: terrain,
                isCoastal: p.coastal,
                areaKm2: p.areaKm2,
                labelPoint: MapPoint(x: p.labelX, y: p.labelY),
                owner: owner,
                development: p.development,
                population: p.population ?? startingPopulation(development: p.development),
                baseTax: startingTax(development: p.development),
                production: startingProduction(development: p.development),
                religion: owner.map { world.countries.religion[$0.index] } ?? .folk,
                fortLevel: startingFort(development: p.development, isCapital: capitals.contains(index))
            )
        }

        for (index, p) in file.provinces.enumerated() {
            for other in p.adjacent {
                world.provinces.connect(ProvinceID(index), ProvinceID(other))
            }
        }

        try buildPops(file, into: &world)

        for (index, c) in file.countries.enumerated() {
            world.countries.capital[index] = ProvinceID(c.capital)
            if let lord = c.overlord {
                guard let lordID = world.countries.id(forTag: lord) else { throw LoadError.unknownValue("overlord \(lord)") }
                guard let kind = c.subjectType.flatMap(SubjectType.init(rawValue:)) else {
                    throw LoadError.unknownValue("subject type \(c.subjectType ?? "nil")")
                }
                world.countries.overlord[index] = lordID
                world.countries.subjectType[index] = kind
            }
        }
        for pair in file.riverBorders ?? [] where pair.count == 2 {
            world.riverBorders.insert(ProvincePair(ProvinceID(pair[0]), ProvinceID(pair[1])))
        }
        world.provinceSeas = Array(repeating: [], count: world.provinces.count)
        for zone in file.seaZones ?? [] {
            let id = world.seaZones.add(name: zone.name)
            world.seaZones.coast[id.index] = zone.coast.map(ProvinceID.init)
            for p in zone.coast where p < world.provinces.count {
                world.provinceSeas[p].append(id)
            }
        }
        for (k, zone) in (file.seaZones ?? []).enumerated() {
            world.seaZones.neighbors[k] = zone.adjacent.map(SeaZoneID.init)
        }
        world.rivers = (file.rivers ?? []).map { river in
            MapPolyline(name: river.name, points: river.points.compactMap { $0.count == 2 ? SIMD2($0[0], $0[1]) : nil })
        }
        return world
    }
}

// MARK: - JSON shape (matches tools/mapgen/mapgen.py)

struct ScenarioFile: Decodable {
    struct Map: Decodable {
        let width: Int
        let height: Int
        let pixelsPerDegree: Double
        let longitudeMin: Double
        let latitudeMax: Double
    }

    struct State: Decodable {
        let name: String
        let region: Int
    }

    struct Country: Decodable {
        let tag: String
        let name: String
        let color: [Int]
        let government: String
        let religion: String
        let capital: Int
        let slavery: Double?
        let overlord: String?
        let subjectType: String?
    }

    struct Culture: Decodable {
        let id: String
        let name: String
        let family: String
    }

    /// [culture index, religion, sect or null, share]
    struct PopShare: Decodable {
        let culture: Int
        let religion: String
        let sect: String?
        let share: Double

        init(from decoder: Decoder) throws {
            var c = try decoder.unkeyedContainer()
            culture = try c.decode(Int.self)
            religion = try c.decode(String.self)
            if try c.decodeNil() {
                sect = nil
            } else {
                sect = try c.decode(String.self)
            }
            share = try c.decode(Double.self)
        }
    }

    /// [order, strength]
    struct OrderPresence: Decodable {
        let order: String
        let strength: Double

        init(from decoder: Decoder) throws {
            var c = try decoder.unkeyedContainer()
            order = try c.decode(String.self)
            strength = try c.decode(Double.self)
        }
    }

    struct Province: Decodable {
        let name: String
        let state: Int
        let owner: String?
        let latitude: Double
        let longitude: Double
        let terrain: String
        let development: Int
        let population: Double?
        let pops: [PopShare]?
        let orders: [OrderPresence]?
        let coastal: Bool
        let areaKm2: Double
        let labelX: Int
        let labelY: Int
        let adjacent: [Int]
    }

    struct River: Decodable {
        let name: String
        let points: [[Double]]
    }

    let map: Map
    let regions: [String]
    let cultures: [Culture]?
    let riverBorders: [[Int]]?
    let seaZones: [SeaZone]?

    struct SeaZone: Decodable {
        let name: String
        let adjacent: [Int]
        let coast: [Int]
    }
    let rivers: [River]?
    let states: [State]
    let countries: [Country]
    let provinces: [Province]
}
